-- State, keyed by src/dst tuple
nasdaq_nordicmarkets_consolidatedfeed_tip_v3_10_18_7.conversation = {}
nasdaq_nordicmarkets_consolidatedfeed_tip_v3_10_18_7.conversation.flows = {}

-- Revisit replay cursor for stream sequences: which frame is being
-- re-dissected and which memoized occurrence within it is next
nasdaq_nordicmarkets_consolidatedfeed_tip_v3_10_18_7.stream_frame = nil
nasdaq_nordicmarkets_consolidatedfeed_tip_v3_10_18_7.stream_occurrence = 0

-- Conversation key for the current packet (src/dst tuple)
nasdaq_nordicmarkets_consolidatedfeed_tip_v3_10_18_7.conversation.key = function(packet)
  return string.format("%s|%s|%s|%s", tostring(packet.src), packet.src_port, tostring(packet.dst), packet.dst_port)
end


-- Get/create our protocol's data record for the current packet's flow
nasdaq_nordicmarkets_consolidatedfeed_tip_v3_10_18_7.conversation.data = function(packet)
  local key = nasdaq_nordicmarkets_consolidatedfeed_tip_v3_10_18_7.conversation.key(packet)
  local data = nasdaq_nordicmarkets_consolidatedfeed_tip_v3_10_18_7.conversation.flows[key]
  if data == nil then
    data = { accepted_sequence_number = { last = nil, frames = {} }, sequence = { next = nil, frames = {} } }
    nasdaq_nordicmarkets_consolidatedfeed_tip_v3_10_18_7.conversation.flows[key] = data
  end
  return data
end


-- Handle to the current packet's conversation data
nasdaq_nordicmarkets_consolidatedfeed_tip_v3_10_18_7.conversation.current = nil


-----------------------------------------------------------------------
-- Protocol Functions
-----------------------------------------------------------------------

-- trim trailing spaces
trim_right_spaces = function(str)
  local finish = str:len()

  while finish > 0 and str:byte(finish) == 0x20 do
    finish = finish - 1
  end

  return str:sub(1, finish)
end


-----------------------------------------------------------------------
-- Nasdaq NordicMarkets ConsolidatedFeed 3.10.18.7 Tip Functions
-----------------------------------------------------------------------

-- Tokens of a tip message: offset and length of each ';' terminated token, a '\' escaping the byte after it
nasdaq_nordicmarkets_consolidatedfeed_tip_v3_10_18_7.tip_tokens = function(buffer, offset, size)
  local text = buffer(offset, size):raw()
  local tokens = {}
  local start = 1
  local index = 1
  while index <= #text do
    local byte = text:byte(index)
    if byte == 92 then
      index = index + 2
    elseif byte == 59 then
      if index > start then
        tokens[#tokens + 1] = { offset = offset + start - 1, length = index - start }
      end
      index = index + 1
      start = index
    else
      index = index + 1
    end
  end
  if start <= #text then
    tokens[#tokens + 1] = { offset = offset + start - 1, length = #text - start + 1 }
  end
  return tokens
end

-- Text of a value with its '\' escapes removed
nasdaq_nordicmarkets_consolidatedfeed_tip_v3_10_18_7.tip_text = function(range)
  return (range:string():gsub("\\(.)", "%1"))
end

-- Tag code of a token: upper case letters then one lower case letter
nasdaq_nordicmarkets_consolidatedfeed_tip_v3_10_18_7.tip_code = function(buffer, token)
  return buffer(token.offset, token.length):string():match("^%u*%l")
end


