-- Dissect: Sellers At Level
nasdaq_nordicmarkets_consolidatedfeed_tip_v3_10_18_7.sellers_at_level.dissect = function(buffer, offset, size, packet, parent)
  local range = buffer(offset, size)
  local text = nasdaq_nordicmarkets_consolidatedfeed_tip_v3_10_18_7.tip_text(range)
  local level, rest = text:match("^(%d+):(.*)$")
  if level == nil then
    parent:add_tvb_expert_info(nasdaq_nordicmarkets_consolidatedfeed_tip_v3_10_18_7.experts.invalid_value, range, "Sellers At Level: indexed value without a level: "..text)
