-- Dissect: Server Payload
nasdaq_nordicmarkets_consolidatedfeed_tip_v3_10_18_7.server_payload.dissect = function(buffer, offset, packet, parent, server_packet_type)
  -- Dissect Debug Packet
  if server_packet_type == "+" then
    return nasdaq_nordicmarkets_consolidatedfeed_tip_v3_10_18_7.debug_packet.dissect(buffer, offset, packet, parent)
  end
  -- Dissect Login Accepted Packet
  if server_packet_type == "A" then
    return nasdaq_nordicmarkets_consolidatedfeed_tip_v3_10_18_7.login_accepted_packet.dissect(buffer, offset, packet, parent)
  end
  -- Dissect Login Rejected Packet
  if server_packet_type == "J" then
    return nasdaq_nordicmarkets_consolidatedfeed_tip_v3_10_18_7.login_rejected_packet.dissect(buffer, offset, packet, parent)
  end
  -- Dissect Sequenced Data Packet
  if server_packet_type == "S" then
    return nasdaq_nordicmarkets_consolidatedfeed_tip_v3_10_18_7.sequenced_data_packet.dissect(buffer, offset, packet, parent)
  end
  -- Dissect Server Heartbeat
  if server_packet_type == "H" then
    return nasdaq_nordicmarkets_consolidatedfeed_tip_v3_10_18_7.server_heartbeat.dissect(buffer, offset, packet, parent)
  end
  -- Dissect End Of Session
  if server_packet_type == "Z" then
    return nasdaq_nordicmarkets_consolidatedfeed_tip_v3_10_18_7.end_of_session.dissect(buffer, offset, packet, parent)
  end

  return offset
end

