end

-- Connection roles for Nasdaq NordicMarkets ConsolidatedFeed Tip 3.10.18.7: Client is the initiator, Server is the acceptor
-- Initiator endpoint of each conversation, recorded from its first frame
local initiators = {}

-- Conversations whose first frame proved to be the acceptor's: the heuristic swaps the sides
local swapped = {}

-- Endpoint key of an address and port
local function endpoint(address, port)
  return tostring(address)..":"..tostring(port)
end


-- Conversation key, the same in both directions
local function conversation(packet)
  local source = endpoint(packet.src, packet.src_port)
  local destination = endpoint(packet.dst, packet.dst_port)

  if source < destination then
    return source.." "..destination
  end

  return destination.." "..source
end


-- Connection role of the frame's sender
nasdaq_nordicmarkets_consolidatedfeed_tip_v3_10_18_7.role = function(packet)
  if omi_nasdaq_nordicmarkets_consolidatedfeed_tip_v3_10_18_7.prefs.assume_role == 1 then
    return "initiator"
  end

  if omi_nasdaq_nordicmarkets_consolidatedfeed_tip_v3_10_18_7.prefs.assume_role == 2 then
    return "acceptor"
  end

  local acceptor_port = omi_nasdaq_nordicmarkets_consolidatedfeed_tip_v3_10_18_7.prefs.acceptor_port

  if acceptor_port ~= 0 and packet.dst_port == acceptor_port then
    return "initiator"
  end

  if acceptor_port ~= 0 and packet.src_port == acceptor_port then
    return "acceptor"
  end

  local key = conversation(packet)
  local sender = endpoint(packet.src, packet.src_port)

  if initiators[key] == nil then
    initiators[key] = sender
  end

  local sender_initiated = initiators[key] == sender

  if omi_nasdaq_nordicmarkets_consolidatedfeed_tip_v3_10_18_7.prefs.swap_sides then
    sender_initiated = not sender_initiated
  end

  if swapped[key] then
    sender_initiated = not sender_initiated
  end

  if sender_initiated then
    return "initiator"
  end

  return "acceptor"
end


-- Swap the resolved sides of the frame's conversation
nasdaq_nordicmarkets_consolidatedfeed_tip_v3_10_18_7.swap = function(packet)
  local key = conversation(packet)
  swapped[key] = not swapped[key]
end


-- Dissector for Nasdaq NordicMarkets ConsolidatedFeed Tip 3.10.18.7
function omi_nasdaq_nordicmarkets_consolidatedfeed_tip_v3_10_18_7.dissector(buffer, packet, parent)
  -- Set protocol name
  packet.cols.protocol = omi_nasdaq_nordicmarkets_consolidatedfeed_tip_v3_10_18_7.name

  -- Dissect protocol
  local protocol = parent:add(omi_nasdaq_nordicmarkets_consolidatedfeed_tip_v3_10_18_7, buffer(), omi_nasdaq_nordicmarkets_consolidatedfeed_tip_v3_10_18_7.description, "("..buffer:len().." Bytes)")

  local role = nasdaq_nordicmarkets_consolidatedfeed_tip_v3_10_18_7.role(packet)

  if role == "initiator" then
    return nasdaq_nordicmarkets_consolidatedfeed_tip_v3_10_18_7.client_packet.dissect(buffer, packet, protocol)
  end

  return nasdaq_nordicmarkets_consolidatedfeed_tip_v3_10_18_7.server_packet.dissect(buffer, packet, protocol)
end


