local function omi_nasdaq_nordicmarkets_consolidatedfeed_tip_v3_10_18_7_tcp_initiator_heuristic(buffer, packet, parent)
  -- Verify packet length
  if not nasdaq_nordicmarkets_consolidatedfeed_tip_v3_10_18_7.client_packet.requiredsize(buffer) then return false end

