local function omi_nasdaq_nordicmarkets_consolidatedfeed_tip_v3_10_18_7_tcp_acceptor_heuristic(buffer, packet, parent)
  -- Verify packet length
  if not nasdaq_nordicmarkets_consolidatedfeed_tip_v3_10_18_7.server_packet.requiredsize(buffer) then return false end

  -- Verify the frame matches this side's fingerprint
  if not nasdaq_nordicmarkets_consolidatedfeed_tip_v3_10_18_7.server_packet.fingerprint(buffer) then return false end

