  packet.conversation = omi_nasdaq_nordicmarkets_consolidatedfeed_tip_v3_10_18_7
  omi_nasdaq_nordicmarkets_consolidatedfeed_tip_v3_10_18_7.dissector(buffer, packet, parent)

