end

-- Dissector Heuristic for Nasdaq NordicMarkets ConsolidatedFeed Tip 3.10.18.7 (Tcp): apply the heuristic of the sender's connection role
local function omi_nasdaq_nordicmarkets_consolidatedfeed_tip_v3_10_18_7_tcp_heuristic(buffer, packet, parent)
  local role = nasdaq_nordicmarkets_consolidatedfeed_tip_v3_10_18_7.role(packet)
  local initiator = omi_nasdaq_nordicmarkets_consolidatedfeed_tip_v3_10_18_7_tcp_initiator_heuristic
  local acceptor = omi_nasdaq_nordicmarkets_consolidatedfeed_tip_v3_10_18_7_tcp_acceptor_heuristic

  local first, second = initiator, acceptor

  if role == "acceptor" then
    first, second = acceptor, initiator
  end

  if first(buffer, packet, parent) then
    return true
  end

  -- The other side may have sent this conversation's first frame: swap, and swap back if it cannot claim either
  nasdaq_nordicmarkets_consolidatedfeed_tip_v3_10_18_7.swap(packet)

  if second(buffer, packet, parent) then
    return true
  end

  nasdaq_nordicmarkets_consolidatedfeed_tip_v3_10_18_7.swap(packet)

  return false
end

